/*	Work out who is due a nudge or has run out of time.
	One item per action. Nothing on a quiet day, which is correct rather than a failure.
	Role names, the verb and email styling all come from Config, never hardcoded	*/

const cfg = $('Config').first().json;

/*	A random, unguessable token. 32 bytes from a secure source, hex encoded. It is
	never derived from the event or contact ID. Uses the crypto module where the Code
	node allows it, otherwise the Web Crypto API	*/
const randomToken = () => {
	let bytes = null;
	try {
		bytes = Array.from(require('crypto').randomBytes(32));
	} catch (error) {
		if (typeof crypto !== 'undefined' && crypto.getRandomValues) {
			bytes = Array.from(crypto.getRandomValues(new Uint8Array(32)));
		}
	}
	if (!bytes) {
		throw new Error('No secure random source available. Allow the crypto module in Code nodes (NODE_FUNCTION_ALLOW_BUILTIN=crypto).');
	}
	return bytes.map((b) => b.toString(16).padStart(2, '0')).join('');
};

const ctx = $('Which Events To Check').first().json;

const coordRole = String(cfg.COORDINATOR_ROLE_NAME).trim();
const fallbackRole = String(cfg.FALLBACK_ROLE_NAME || 'Instructor').trim();
const remindersKey = String(cfg.REMINDERS_FIELD_KEY).trim();
const trueValues = String(cfg.CHECKBOX_TRUE_VALUES).split(',').map(v => v.trim().toLowerCase());
const firstDays = Number(cfg.REMINDER_FIRST_DAYS);
const secondDays = Number(cfg.REMINDER_SECOND_DAYS);
const expiryDays = Number(cfg.EXPIRY_DAYS);

/*	The verb for what an instructor does with an event. The literal is a last resort if
	config is blank, not the setting - change VERB_BASE in Config	*/
const verb = String(cfg.VERB_BASE || 'deliver').trim();

/*	Fetch Draft Events pages through the events, one item per page, so every page is
	read. Only reading the first page would silently skip events beyond the first 100	*/
const events = {};
for (const page of $input.all()) {
	for (const edge of ((((page.json.data || {}).events || {}).edges) || [])) {
		events[String(edge.node.id)] = edge.node;
	}
}

/*	SAFETY CATCH. Only events with the reminders field set to Yes are chased.
	No, unset and absent all mean no. Matched on key so the label can be renamed	*/
const optedIn = (ev) => {
	for (const cf of (ev.customFieldValues || [])) {
		if (String(cf.definitionKey || '') !== remindersKey) { continue; }
		return trueValues.indexOf(String(cf.value === null || cf.value === undefined ? '' : cf.value).trim().toLowerCase()) !== -1;
	}
	return false;
};

const esc = (v) => String(v === null || v === undefined ? '' : v)
	.split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;').split('"').join('&quot;');

/*	The email frame, the button and the palette all live in Config, so a change to the
	look is made in one place per workflow rather than hunted through code. Pipe separated
	because the font list itself contains commas	*/
const pal = {};
for (const part of String(cfg.EMAIL_PALETTE || '').split('|')) {
	const at = part.indexOf('=');
	if (at > 0) { pal[part.slice(0, at).trim()] = part.slice(at + 1).trim(); }
}

/*	Palette tokens first, then the content, so a colour name appearing inside the body
	cannot be substituted twice	*/
const fill = (tpl, extra) => {
	let s = String(tpl || '');
	for (const k of Object.keys(pal)) { s = s.split('%%' + k + '%%').join(pal[k]); }
	for (const k of Object.keys(extra || {})) { s = s.split('%%' + k + '%%').join(extra[k]); }
	return s;
};

const emailShell = (inner) => fill(cfg.EMAIL_SHELL, { BRAND: esc(cfg.BRAND_NAME), BODY: inner });
const emailButton = (url, label) => fill(cfg.EMAIL_BUTTON, { URL: esc(url), LABEL: esc(label) });

const out = [];
const now = Date.now();

for (const row of (ctx.openRows || [])) {
	const ev = events[String(row.event_id)];
	if (!ev) { continue; }
	if (!optedIn(ev)) { continue; }
	if (String(ev.lifecycleState || '') !== 'draft') { continue; }

	/*	If staffing is already complete there is nobody left to chase for this event.
		The coordinator role is skipped, because it is filled by hand and never answers	*/
	const staff = ((ev.staff || {}).edges || []).map(e => e.node);
	let complete = false;
	for (const req of (ev.requiredStaff || [])) {
		const roleName = String((req.staffRole || {}).name || '').trim();
		const qty = Number(req.quantity || 0);
		if (roleName === coordRole || qty === 0) { continue; }
		if (staff.filter(s => String((s.staffRole || {}).name || '').trim() === roleName).length >= qty) { complete = true; }
	}
	if (complete) { continue; }

	const since = String(row.last_reminder_at || row.responded_at || row.updated_at || '');
	const t = new Date(since).getTime();
	if (isNaN(t)) { continue; }
	const ageDays = Math.floor((now - t) / 86400000);

	let action = '';
	if (ageDays >= expiryDays) { action = 'expire'; }
	else if (ageDays >= secondDays) { action = 'remind2'; }
	else if (ageDays >= firstDays) { action = 'remind1'; }
	if (action === '') { continue; }

	const coordinatorIds = staff.filter(s => String((s.staffRole || {}).name || '').trim() === coordRole).map(s => s.id);
	const isExpiry = action === 'expire';

	/*	A reminder goes to the person being asked, who may not be staff on the event, so
		it is sent as a contact. An expiry notice goes to the coordinator, who is staff	*/
	if (isExpiry && coordinatorIds.length === 0) { continue; }

	/*	Whether this person is actually on the event decides what the expiry notice can
		truthfully say. Under the pre-staffed pattern somebody is invited after being
		assigned, so silence does not mean they are absent from the event	*/
	const onEvent = staff.some(s => s.contact && String(s.contact.id) === String(row.contact_id));

	const name = String(row.contact_name || 'the person invited');
	/*	The reminder carries the person's personal token. A row recorded by the coordinator
		on their behalf may not have one yet, so one is created here and saved by Record The Chase	*/
	const token = row.token ? String(row.token) : randomToken();
	const link = String(cfg.RESPONSE_BASE_URL) + '?e=' + encodeURIComponent(row.event_id) + '&c=' + encodeURIComponent(row.contact_id) + '&t=' + encodeURIComponent(token);

	const expiryBody = emailShell(
		'<p style="margin:0 0 6px;color:' + pal.AMBER + ';font-size:13px;font-weight:600;">No answer after ' + expiryDays + ' days</p>'
		+ '<p style="margin:0 0 18px;font-size:20px;font-weight:600;color:' + pal.INK + ';">' + esc(name) + '</p>'
		+ '<p style="margin:0 0 16px;">They have not given a firm answer about <strong>' + esc(ev.title) + '</strong>.</p>'
		+ (onEvent
			? '<div style="background:' + pal.AMBERBG + ';border-left:3px solid ' + pal.AMBER + ';padding:12px 14px;margin:0 0 16px;">'
				+ '<p style="margin:0;"><strong>They are still assigned to the event.</strong> Nothing has been changed automatically, so if you want to ask somebody else you will need to take them off it first.</p></div>'
			: '<p style="margin:0 0 16px;color:' + pal.MUTED + ';">They are not assigned to the event and nothing has been changed. You may want to ask somebody else.</p>'));

	const reminderBody = emailShell(
		'<p style="margin:0 0 16px;">Hi ' + esc(String(name).split(' ')[0]) + ',</p>'
		+ '<p style="margin:0 0 6px;color:' + pal.MUTED + ';font-size:13px;">Still waiting to hear</p>'
		+ '<p style="margin:0 0 18px;font-size:20px;font-weight:600;color:' + pal.INK + ';">' + esc(ev.title) + '</p>'
		+ '<p style="margin:0 0 4px;">We asked whether you are available to ' + esc(verb) + ' this event and do not yet have a firm answer.</p>'
		+ emailButton(link, 'Give your answer')
		+ '<p style="margin:0 0 16px;color:' + pal.MUTED + ';">If the answer is no, saying so helps us ask someone else quickly.</p>'
		+ '<p style="margin:20px 0 8px;padding-top:14px;border-top:1px solid ' + pal.LINE + ';color:' + pal.MUTED + ';font-size:13px;">' + esc(cfg.BRAND_NAME) + '</p>');

	out.push({ json: {
		action: action,
		isExpiry: isExpiry,
		onEvent: onEvent,
		eventId: String(row.event_id),
		eventTitle: String(ev.title || row.event_title || ''),
		contactId: String(row.contact_id),
		contactName: name,
		contactEmail: String(row.contact_email || ''),
		token: token,
		staffRole: String(row.staff_role || fallbackRole),
		coordinatorIds: coordinatorIds,
		ageDays: ageDays,
		status: isExpiry ? 'expired' : 'reminded',
		logStatus: isExpiry ? 'warning' : 'success',
		now: new Date().toISOString(),
		subject: isExpiry
			? 'No answer yet from ' + name + ' - ' + ev.title
			: 'Reminder: are you available to ' + verb + ' ' + ev.title + '?',
		body: isExpiry ? expiryBody : reminderBody,
		logMessage: isExpiry
			? 'No firm answer from ' + name + ' after ' + ageDays + ' days. ' + (onEvent ? 'They are still assigned to the event and have not been removed.' : 'They are not assigned to the event.') + ' ' + coordRole + ' notified.'
			: 'Reminder sent to ' + name + ', ' + ageDays + ' days since their last response.',
		logPayload: JSON.stringify({ action: action, ageDays: ageDays, contactId: row.contact_id, onEvent: onEvent })
	} });
}

return out;

/*	Work out which events this automation is involved with, and which of those have
	somebody worth chasing. Those are two different sets and the sweep needs both.

	Every event with an invitation row is refreshed, whether or not anybody is being
	chased, because the status field can go stale for reasons that have nothing to do
	with a response - a coordinator being added after staffing completed, somebody being
	taken off by hand. Nothing in Administrate tells us when that happens, so a daily
	pass over the events we already know about is how it gets noticed.

	The invitations table is the only record of who has been asked, which is also why the
	send log matters: until Administrate exposes it, a row exists only once somebody has
	clicked their link	*/

const cfg = $('Config').first().json;
const chaseable = String(cfg.CHASEABLE_STATUSES).split(',').map(s => s.trim().toLowerCase());

const rows = $input.all().map(i => i.json).filter(r => r && r.event_id);
const open = rows.filter(r => chaseable.indexOf(String(r.status || '').toLowerCase()) !== -1);

/*	Every event we hold a row for, not only the ones with somebody outstanding	*/
const ids = [];
for (const r of rows) {
	if (ids.indexOf(String(r.event_id)) === -1) { ids.push(String(r.event_id)); }
}

/*	No rows at all means this automation has never touched anything. Nothing to do,
	which is the normal case on a fresh tenant rather than a failure	*/
if (ids.length === 0) { return []; }

return [{ json: { eventIds: ids, openRows: open } }];

/*	One item per draft event we hold invitation rows for, so each gets its summary
	refreshed. This runs whether or not anybody was chased: the point is to notice
	changes nothing else tells us about, such as a coordinator added after staffing
	already completed, which otherwise leaves the completion email permanently owed.

	Published and cancelled events are skipped. Their staffing decision has been made
	and the field will not change again	*/

/*	One input item per page of events. All pages are read, and an event is only
	listed once even if it somehow appears on two pages	*/
const out = [];
const seen = {};

for (const page of $input.all()) {
	for (const edge of ((((page.json.data || {}).events || {}).edges) || [])) {
		const ev = edge.node || {};
		if (String(ev.lifecycleState || '') !== 'draft') { continue; }
		if (seen[String(ev.id)]) { continue; }
		seen[String(ev.id)] = true;
		out.push({ json: { eventId: String(ev.id), eventTitle: String(ev.title || '') } });
	}
}

return out;
